<script setup>import{inject,reactive,watch,ref}from'vue';import api from '../../../../services/api';const s=inject('clinicAdmin'),confirming=ref(false);const form=reactive({});watch(s.clinic,v=>Object.assign(form,v||{}),{immediate:true});async function save(){await s.run(async()=>{await api.patch('/v1/platform/tenants/'+s.clinic.value.id,{name:form.name,timezone:form.timezone,status:form.status});await s.load(s.clinic.value.id)},'Clinic settings saved.')}async function suspend(){await s.run(async()=>{await api.patch('/v1/platform/tenants/'+s.clinic.value.id,{name:form.name,timezone:form.timezone,status:'suspended'});confirming.value=false;await s.load(s.clinic.value.id)},'Clinic suspended.')}</script><template><div class="space-y-6"><section class="admin-card max-w-3xl"><h2 class="text-lg font-bold">Clinic Settings</h2><form class="form-grid mt-6" @submit.prevent="save"><label class="field">Clinic name<input v-model="form.name" required></label><label class="field">Timezone<input v-model="form.timezone" required></label><label class="field">Status<select v-model="form.status"><option>active</option><option>suspended</option></select></label><button class="btn self-end">Save Settings</button></form></section><section class="admin-card max-w-3xl border-rose-200"><h2 class="text-lg font-bold text-rose-800">Danger Zone</h2><p class="mt-2 text-sm text-slate-600">Suspending a clinic immediately prevents tenant access.</p><button v-if="!confirming" class="mt-5 rounded-lg border border-rose-300 px-4 py-2 text-sm font-semibold text-rose-700" @click="confirming=true">Suspend Clinic</button><div v-else class="mt-5 rounded-xl bg-rose-50 p-4"><p class="font-semibold text-rose-900">Confirm suspension?</p><div class="mt-3 flex gap-3"><button class="btn-secondary" @click="confirming=false">Cancel</button><button class="rounded-lg bg-rose-700 px-4 py-2 text-sm font-semibold text-white" @click="suspend">Yes, suspend clinic</button></div></div></section></div></template>
